function evidence = f90_xrobo03_extract_evidence(modelPath, outDir)
%f90_xrobo03_extract_evidence Fix Simscape sensing-port classification.
%   Scenario simulation and metric extraction remain exactly SCORING_CORE/METRICS.  Only
%   the static structure audit is replaced by the connection-aware
%   GROUP_SCORING audit; the SCORING_CORE audit is retained inside the evidence as provenance.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end

taskRoot = fileparts(mfilename("fullpath"));
policyPath = fullfile(taskRoot, ...
    "f90_xrobo03_static_audit_policy.json");
modelPresenceBefore = xp9_file_presence_file(modelPath);
evidence = f90_xrobo03_extract_evidence_core(modelPath, outDir);
evidence.superseded_static_audit = evidence.static_audit;
evidence.superseded_static_audit_current_policy_file_presence = ...
    evidence.static_audit_policy_file_presence;
try
    evidence.static_audit = f90_xrobo03_static_audit( ...
        modelPath, policyPath);
    evidence.static_audit_current_pass = true;
catch ME
    evidence.static_audit = localEmptyAudit;
    evidence.static_audit_current_pass = false;
    evidence.errors.static_audit = localError(ME);
end
modelPresenceAfter = xp9_file_presence_file(modelPath);
assert(modelPresenceBefore == modelPresenceAfter, ...
    "SimuVerity:F90:XROBO03:CandidateChanged", ...
    "The read-only GROUP_SCORING audit changed the sealed candidate model.");
assert(~isfield(evidence, "model_file_presence") || ...
    lower(string(evidence.model_file_presence)) == modelPresenceAfter, ...
    "SimuVerity:F90:XROBO03:CandidateBindingMismatch", ...
    "Scenario evidence and GROUP_SCORING static evidence bind different candidates.");

evidence.structure_evidence_schema = ...
    "simuverity.f90-xrobo03-structure-evidence.v1";
evidence.static_audit_policy_file_presence = xp9_file_presence_file(policyPath);
evidence.static_audit_engine_file_presence = xp9_file_presence_file(fullfile( ...
    taskRoot, "f90_xrobo03_static_audit.m"));
evidence.current_evidence_engine_file_presence = xp9_file_presence_file(fullfile( ...
    taskRoot, "f90_xrobo03_extract_evidence_core.m"));
evidence.supersedes_static_audit_current_in_this_evaluation = true;
evidence.candidate_evidence_ready = true;
localWriteJson(fullfile(outDir, "evidence.json"), evidence);
end

function audit = localEmptyAudit
audit = struct( ...
    "block_count", 0, ...
    "dynamic_block_count", 0, ...
    "physical_joint_count", 0, ...
    "spatial_contact_count", 0, ...
    "actuated_joint_count", 0, ...
    "physical_sensor_count", 0, ...
    "joint_sense_channel_count", 0, ...
    "explicit_sensor_channel_count", 0, ...
    "contact_measurement_channel_count", 0, ...
    "standard_public_output_count", 0, ...
    "constant_or_workspace_output_count", 0, ...
    "display_name_identity_used", false, ...
    "candidate_mask_identity_used", false, ...
    "joint_identity_fields", strings(0, 1), ...
    "measurement_channel_rule", "", ...
    "public_output_origin_rows", struct([]));
end

function value = localError(ME)
value = struct( ...
    "identifier", string(ME.identifier), ...
    "message", string(ME.message), ...
    "report", string(getReport(ME, "extended", ...
        "hyperlinks", "off")));
end

function localWriteJson(pathValue, value)
fid = fopen(pathValue, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:F90:XROBO03:JsonOpen", ...
    "Cannot write GROUP_SCORING evidence output: %s", pathValue);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
end
